#include <stdio.h>

int main() {
  int i     = 0;
  int j     = 0;
  int total = 0;
outer:
  j = 0;
inner:
  total = total + (i * j);
  j     = j + 1;
  if (j < 3)
    goto inner;
  i = i + 1;
  if (i < 4)
    goto outer;
  printf("%d\n", total);
  return 0;
}



